type createFlags struct {
	outDir            string
	output            string
	name              string
	templateVersion   string
	values            []string
	sets              []string
	force             bool
	noInput           bool
	installSkills     bool
	skipInstallSkills bool
}

var intCreateFlags createFlags

var intCreateCmd = &cobra.Command{
	Use:   "create <template>",
	Short: "Create a new integration",
	Long:  "Scaffold a new integration from the official Intropy template library. The positional argument selects which template subdirectory to render (e.g. 'hello-world'). After scaffolding, offers to install the Intropy agent skills collection into the new integration; --install-skills installs and --skip-install-skills skips without prompting, otherwise the prompt is skipped with --no-input or when stdin is not a terminal.",
	Args:  cobra.ExactArgs(1),
	RunE: func(cmd *cobra.Command, args []string) error {
		sets, err := template.ParseSets(intCreateFlags.sets)
		if err != nil {
			return err
		}
		if intCreateFlags.output != "" && intCreateFlags.output != "json" {
			return newUsageErrorf("invalid output format %q (allowed: json)", intCreateFlags.output)
		}
		outputJSON := ""
		if intCreateFlags.output == "json" {
			outputJSON = "-"
		}
		outputDir, err := resolveCreateName(intCreateFlags.name, intCreateFlags.outDir, sets)
		if err != nil {
			return err
		}
		ctx, cancel := signal.NotifyContext(cmd.Context(), os.Interrupt, syscall.SIGTERM)
		defer cancel()
		if err := template.Create(ctx, template.CreateOptions{
			Template:   args[0],
			OutputDir:  outputDir,
			Version:    intCreateFlags.templateVersion,
			SetValues:  sets,
			Files:      intCreateFlags.values,
			Force:      intCreateFlags.force,
			NoInput:    intCreateFlags.noInput,
			OutputJSON: outputJSON,
			Stdin:      cmd.InOrStdin(),
			Stdout:     cmd.OutOrStdout(),
			Stderr:     cmd.ErrOrStderr(),
			UserAgent:  "intropy-cli/" + version,
		}); err != nil {
			return err
		}
		if err := maybeInstallSkills(ctx, cmd.InOrStdin(), cmd.ErrOrStderr(), intCreateFlags.installSkills, intCreateFlags.skipInstallSkills, intCreateFlags.noInput, outputDir); err != nil {
			return fmt.Errorf("integration created, but skills install failed: %w", err)
		}
		return nil
	},
}

// resolveCreateName folds the -n shorthand into the set map and derives the
// output dir. -n is sugar for --set name=<v>; it also defaults --output when
// -o is absent.
func resolveCreateName(name, output string, sets map[string]any) (string, error) {
	if name == "" {
		return output, nil
	}
	if _, ok := sets["name"]; ok {
		return "", newUsageErrorf("cannot combine --name with --set name= (they conflict)")
	}
	sets["name"] = name
	if output == "" {
		output = name
	}
	return output, nil
}

func init() {
	f := intCreateCmd.Flags()
	f.StringVarP(&intCreateFlags.outDir, "out-dir", "o", "", "destination directory (defaults to --name)")
	f.StringVar(&intCreateFlags.output, "output", "", flagUsageOutputJSONOnly)
	_ = intCreateCmd.MarkFlagDirname("out-dir")
	f.StringVarP(&intCreateFlags.name, "name", "n", "", "integration name; sets the template's 'name' parameter and, unless --out-dir is set, becomes the output directory")
	f.StringVar(&intCreateFlags.templateVersion, "template-version", "", flagUsageTemplateVer)
	f.StringArrayVarP(&intCreateFlags.values, "values", "f", nil, "values file in YAML/JSON (repeatable; use - to read one doc from stdin)")
	f.StringArrayVarP(&intCreateFlags.sets, "set", "s", nil, "set a value as key=value (repeatable)")
	f.BoolVar(&intCreateFlags.force, "force", false, "allow rendering into a non-empty output directory")
	f.BoolVar(&intCreateFlags.noInput, "no-input", false, "disable interactive prompts for missing values")
	f.BoolVar(&intCreateFlags.installSkills, "install-skills", false, "install the Intropy agent skills collection without prompting")
	f.BoolVar(&intCreateFlags.skipInstallSkills, "skip-install-skills", false, "skip the agent skills install without prompting")
	intCreateCmd.MarkFlagsMutuallyExclusive("install-skills", "skip-install-skills")
	intCreateCmd.MarkFlagsOneRequired("out-dir", "name")
	intCmd.AddCommand(intCreateCmd)
}

import { useCallback, useEffect, useState } from 'react'
import { api, type DeployState, type Integration, type IntegrationDetail } from './api'
import { Sidebar } from './components/Sidebar'
import { DetailPanel } from './components/DetailPanel'
import { FlowView } from './components/FlowView'
import { DarkModeIcon, LightModeIcon, SystemThemeIcon } from './icons'

const SIDEBAR_COLLAPSED_KEY = 'intropy.sidebar.collapsed'
const THEME_KEY = 'intropy.theme'

type View = 'catalog' | 'flow'

const VIEWS: { id: View; label: string }[] = [
  { id: 'catalog', label: 'Integration Catalog' },
  { id: 'flow', label: 'Integration Flow' },
]

// Theme preference cycles light → dark → system. "system" follows the OS,
// resolved to a concrete light/dark value that drives both data-theme (CSS)
// and the flow canvas colorMode.
type ThemePref = 'light' | 'dark' | 'system'
const THEME_ORDER: ThemePref[] = ['light', 'dark', 'system']
const THEME_META: Record<ThemePref, { Icon: typeof LightModeIcon; label: string }> = {
  light: { Icon: LightModeIcon, label: 'Light' },
  dark: { Icon: DarkModeIcon, label: 'Dark' },
  system: { Icon: SystemThemeIcon, label: 'System' },
}

function prefersDark(): boolean {
  return window.matchMedia('(prefers-color-scheme: dark)').matches
}

function resolveTheme(pref: ThemePref): 'light' | 'dark' {
  return pref === 'system' ? (prefersDark() ? 'dark' : 'light') : pref
}

export default function App() {
  const [integrations, setIntegrations] = useState<Integration[] | null>(null)
  const [selected, setSelected] = useState<string | null>(null)
  const [detail, setDetail] = useState<IntegrationDetail | null>(null)
  const [deployState, setDeployState] = useState<DeployState | null>(null)
  const [deployLoading, setDeployLoading] = useState(false)
  const [deployRefreshing, setDeployRefreshing] = useState(false)
  const [version, setVersion] = useState<string>('')
  const [error, setError] = useState<string | null>(null)
  const [collapsed, setCollapsed] = useState<boolean>(
    () => localStorage.getItem(SIDEBAR_COLLAPSED_KEY) === 'true',
  )
  const [view, setView] = useState<View>('catalog')
  const [theme, setTheme] = useState<ThemePref>(
    () => (localStorage.getItem(THEME_KEY) as ThemePref | null) ?? 'system',
  )
  const [resolvedTheme, setResolvedTheme] = useState<'light' | 'dark'>(() =>
    resolveTheme(theme),
  )

  useEffect(() => {
    localStorage.setItem(SIDEBAR_COLLAPSED_KEY, String(collapsed))
  }, [collapsed])

  // Apply the theme to <html> and track the resolved value. In system mode,
  // also follow live OS changes; explicit modes ignore them.
  useEffect(() => {
    localStorage.setItem(THEME_KEY, theme)
    const apply = () => {
      const resolved = resolveTheme(theme)
      document.documentElement.dataset.theme = resolved
      setResolvedTheme(resolved)
    }
    apply()
    if (theme !== 'system') return
    const mq = window.matchMedia('(prefers-color-scheme: dark)')
    mq.addEventListener('change', apply)
    return () => mq.removeEventListener('change', apply)
  }, [theme])

  const cycleTheme = () =>
    setTheme((t) => THEME_ORDER[(THEME_ORDER.indexOf(t) + 1) % THEME_ORDER.length])

  useEffect(() => {
    api
      .listIntegrations()
      .then(setIntegrations)
      .catch((e: unknown) => setError(errText(e)))
    api
      .health()
      .then((h) => setVersion(h.version))
      .catch(() => {})
  }, [])

  // Auto-select the first integration once the list loads.
  useEffect(() => {
    if (integrations && integrations.length > 0 && !selected) {
      setSelected(integrations[0].path)
    }
  }, [integrations, selected])

  useEffect(() => {
    if (!selected) {
      setDetail(null)
      return
    }
    setDetail(null)
    api
      .getIntegration(selected)
      .then(setDetail)
      .catch((e: unknown) => setError(errText(e)))
  }, [selected])

  // Deployment state loads on its own, because it costs its own thing: reading
  // it refreshes a GitOps checkout over the network, while the detail above is
  // local files. Keeping them apart lets the panel render straight away.
  //
  // A failed lookup is not an error banner: the reason travels inside the state
  // and belongs in the Deployment section, next to the Refresh that retries it.
  useEffect(() => {
    if (!selected) {
      setDeployState(null)
      return
    }
    setDeployState(null)
    setDeployLoading(true)
    let current = true
    api
      .deployState(selected)
      .then((s) => {
        if (current) setDeployState(s)
      })
      .catch((e: unknown) => {
        if (current) setDeployState({ error: errText(e), readAt: new Date().toISOString() })
      })
      .finally(() => {
        if (current) setDeployLoading(false)
      })
    // Selecting another integration while this is in flight must not let the
    // slower answer land on the newer selection.
    return () => {
      current = false
    }
  }, [selected])

  const refreshDeploy = useCallback(() => {
    if (!selected) return
    setDeployRefreshing(true)
    api
      .refreshDeployState(selected)
      .then(setDeployState)
      .catch((e: unknown) =>
        setDeployState({ error: errText(e), readAt: new Date().toISOString() }),
      )
      .finally(() => setDeployRefreshing(false))
  }, [selected])

  return (
    <div className="app">
      <header className="topbar">
        <div className="brand">
          <span className="brand-mark" aria-hidden />
          <span className="brand-name">Intropy</span>
          <span className="brand-sub">dashboard</span>
        </div>
        <nav className="nav">
          {VIEWS.map((v) => (
            <button
              key={v.id}
              className={`nav-item${view === v.id ? ' active' : ''}`}
              onClick={() => setView(v.id)}
              aria-current={view === v.id ? 'page' : undefined}
            >
              {v.label}
            </button>
          ))}
        </nav>
        <div className="topbar-end">
          {version && <span className="version">{version}</span>}
          <ThemeToggle theme={theme} onCycle={cycleTheme} />
        </div>
      </header>

      <div className="layout">
        {view === 'catalog' && (
          <Sidebar
            integrations={integrations}
            selected={selected}
            onSelect={setSelected}
            collapsed={collapsed}
            onToggle={() => setCollapsed((c) => !c)}
          />
        )}
        <main className="content">
          {error && <div className="banner error">{error}</div>}
          {view === 'catalog' ? (
            <DetailPanel
              detail={detail}
              hasSelection={!!selected}
              deploy={{
                state: deployState,
                loading: deployLoading,
                refreshing: deployRefreshing,
                onRefresh: refreshDeploy,
              }}
            />
          ) : (
            <FlowView selected={selected} onSelect={setSelected} theme={resolvedTheme} />
          )}
        </main>
      </div>
    </div>
  )
}

// ThemeToggle cycles the theme preference. The current mode's glyph and a
// title communicate both the active choice and that clicking advances it.
function ThemeToggle({ theme, onCycle }: { theme: ThemePref; onCycle: () => void }) {
  const { Icon, label } = THEME_META[theme]
  return (
    <button
      type="button"
      className="theme-toggle"
      onClick={onCycle}
      title={`Theme: ${label} (click to change)`}
      aria-label={`Theme: ${label}. Click to change.`}
    >
      <Icon className="icon" aria-hidden />
    </button>
  )
}

function errText(e: unknown): string {
  return e instanceof Error ? e.message : String(e)
}

package template

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

type CreateOptions struct {
	Template   string // required; subdirectory in the templates repo holding template.yaml + skeleton/
	OutputDir  string
	Version    string
	SetValues  map[string]any
	Files      []string
	Force      bool
	NoInput    bool
	OutputJSON string // path to write CreateResult JSON; "-" means stdout
	Stdin      io.Reader
	Stdout     io.Writer
	Stderr     io.Writer
	HTTP       *http.Client
	UserAgent  string

	// Test overrides. Production callers leave these zero-valued; the CLI
	// always targets the official template library at integrio-intropy/intropy-templates.
	Owner         string
	Repo          string
	GitHubBaseURL string
}

// CreateResult is the machine-readable summary written when --output-json is
// set. It is the contract chained scaffolder steps consume; field names are
// stable and additive-only.
type CreateResult struct {
	Template  string         `json:"template"`
	Owner     string         `json:"owner"`
	Repo      string         `json:"repo"`
	Version   string         `json:"version"`
	OutputDir string         `json:"outputDir"`
	Values    map[string]any `json:"values"`

	// Dependencies reports what happened to each spec.dependencies entry
	// (including transitive ones): rendered now ("created") or already
	// present ("exists").
	Dependencies []DependencyResult `json:"dependencies,omitempty"`
}

func (o *CreateOptions) applyDefaults() {
	if o.Owner == "" {
		o.Owner = defaultTemplateOwner
	}
	if o.Repo == "" {
		o.Repo = defaultTemplateRepo
	}
	if o.Stdin == nil {
		o.Stdin = os.Stdin
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
}

// Create runs the full scaffold: resolve release, download tarball, extract,
// load manifest, resolve values (with optional interactive prompting), render.
func Create(ctx context.Context, opts CreateOptions) error {
	opts.applyDefaults()
	if err := validateCreateOptions(opts); err != nil {
		return err
	}

	gh := newConfiguredGitHub(opts.HTTP, opts.UserAgent, opts.GitHubBaseURL)
	tag, err := resolveReleaseTag(ctx, gh, opts.Owner, opts.Repo, opts.Version)
	if err != nil {
		return err
	}
	fmt.Fprintf(opts.Stderr, "fetching %s/%s@%s\n", opts.Owner, opts.Repo, tag)

	templateRoot, cleanup, err := downloadTemplate(ctx, gh, opts.Owner, opts.Repo, tag, opts.Template, "intropy-template-*")
	if err != nil {
		return err
	}
	defer cleanup()

	tmpl, values, err := prepareCreateTemplate(templateRoot, opts)
	if err != nil {
		return err
	}

	if err := renderCreateOutput(templateRoot, opts.Template, opts.OutputDir, opts.Force, values); err != nil {
		return err
	}
	fmt.Fprintf(opts.Stderr, "created %s from %s/%s@%s (template %s)\n", opts.OutputDir, opts.Owner, opts.Repo, tag, opts.Template)

	// Dependencies come from the same extracted tarball, so they are always
	// version-locked to the component that declared them.
	depRecords, depResults, err := processDependencies(tmpl, values, opts.OutputDir, &depContext{
		repoRoot: filepath.Dir(templateRoot),
		owner:    opts.Owner,
		repo:     opts.Repo,
		version:  tag,
		stderr:   opts.Stderr,
		visited:  map[string]bool{},
	}, 0)
	if err != nil {
		return err
	}

	// The template field is the repo directory name (opts.Template), not
	// tmpl.Metadata.Name — it is what a later re-fetch needs.
	if err := WriteScaffold(opts.OutputDir, Scaffold{
		SchemaVersion: ScaffoldSchemaVersion,
		Template:      opts.Template,
		Owner:         opts.Owner,
		Repo:          opts.Repo,
		Version:       tag,
		Values:        values,
		Role:          roleFromLabels(tmpl.Metadata.Labels),
		BlockKind:     blockKindFromLabels(tmpl.Metadata.Labels),
		DataFlow:      dataFlowFromLabels(tmpl.Metadata.Labels),
		DependsOn:     depRecords,
	}); err != nil {
		return err
	}

	return maybeWriteCreateResult(opts, tmpl, values, tag, depResults)
}

func validateCreateOptions(opts CreateOptions) error {
	if err := validateTemplateName(opts.Template); err != nil {
		return err
	}
	if opts.OutputDir == "" {
		return errors.New("--out-dir is required")
	}
	return nil
}

func prepareCreateTemplate(templateRoot string, opts CreateOptions) (*Template, map[string]any, error) {
	tmpl, err := LoadTemplate(filepath.Join(templateRoot, templateManifestName))
	if err != nil {
		return nil, nil, err
	}

	prompter := selectPrompter(&opts)
	values, err := Resolve(tmpl, opts.Files, opts.Stdin, opts.SetValues, prompter)
	if err != nil {
		return nil, nil, err
	}
	return tmpl, values, nil
}

func renderCreateOutput(templateRoot, templateName, outputDir string, force bool, values map[string]any) error {
	skelRoot := filepath.Join(templateRoot, templateSkeletonDir)
	if info, err := os.Stat(skelRoot); err != nil || !info.IsDir() {
		return fmt.Errorf("template %q is missing %s/ directory", templateName, templateSkeletonDir)
	}
	if err := ensureOutputDir(outputDir, force); err != nil {
		return err
	}
	return Render(skelRoot, outputDir, values)
}

func maybeWriteCreateResult(opts CreateOptions, tmpl *Template, values map[string]any, tag string, deps []DependencyResult) error {
	if opts.OutputJSON == "" {
		return nil
	}

	absOut, err := filepath.Abs(opts.OutputDir)
	if err != nil {
		absOut = opts.OutputDir
	}
	result := CreateResult{
		Template:     tmpl.Metadata.Name,
		Owner:        opts.Owner,
		Repo:         opts.Repo,
		Version:      tag,
		OutputDir:    absOut,
		Values:       values,
		Dependencies: deps,
	}
	if err := writeOutputJSON(opts.OutputJSON, opts.Stdout, result); err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	return nil
}

func writeOutputJSON(path string, stdout io.Writer, r CreateResult) error {
	data, err := json.MarshalIndent(r, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	if path == "-" {
		_, err := stdout.Write(data)
		return err
	}
	return os.WriteFile(path, data, 0o644)
}

// EnsureOutputDir creates dir if missing and refuses to render into a
// non-empty directory unless force is set.
func EnsureOutputDir(dir string, force bool) error {
	return ensureOutputDir(dir, force)
}

func ensureOutputDir(dir string, force bool) error {
	info, err := os.Stat(dir)
	switch {
	case errors.Is(err, os.ErrNotExist):
		return os.MkdirAll(dir, 0o755)
	case err != nil:
		return err
	case !info.IsDir():
		return fmt.Errorf("--output %s exists and is not a directory", dir)
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return err
	}
	if len(entries) > 0 && !force {
		return fmt.Errorf("--output %s is not empty (use --force to overwrite)", dir)
	}
	return nil
}

// validateTemplateName rejects empty names and anything that could escape the
// extracted tarball root via filepath.Join (separators, parent refs, hidden
// directories). The template argument is user input that we turn directly into
// a path segment, so it has to be sanitized.
func validateTemplateName(name string) error {
	if name == "" {
		return errors.New("template name is required")
	}
	if name == "." || name == ".." || strings.HasPrefix(name, ".") {
		return fmt.Errorf("invalid template name %q", name)
	}
	if strings.ContainsAny(name, `/\`) {
		return fmt.Errorf("invalid template name %q (must be a single path segment)", name)
	}
	return nil
}

func selectPrompter(opts *CreateOptions) Prompter {
	return AutoPrompter(opts.Stdin, opts.Stderr, opts.NoInput)
}

// AutoPrompter returns a StdinPrompter when interactive prompting is viable:
// noInput is false and stdin is a real terminal. In CI / piped contexts it
// returns nil, so Resolve reports a clean "missing required parameter(s)"
// error instead of hanging on a read.
func AutoPrompter(stdin io.Reader, out io.Writer, noInput bool) Prompter {
	if noInput {
		return nil
	}
	f, ok := stdin.(*os.File)
	if !ok || !isTerminal(f.Fd()) {
		return nil
	}
	return NewStdinPrompter(stdin, out)
}

package template

import (
	"fmt"
	"maps"
	"slices"
)

// Reserved value keys carry structured, non-parameter data into a render.
//
// spec.parameters is scalar-only by design, so a skeleton cannot declare "the
// list of connectors" as a parameter. These keys are how it gets one anyway:
// the caller injects the structures after validation, and the skeleton ranges
// over them. Which files a render produces is then decided by a spec.files
// condition over the same data.
const (
	ReservedTopologyKey  = "topology"
	ReservedComponentKey = "component"
	ReservedGitopsKey    = "gitops"
	ReservedScaffoldKey  = "scaffold"

	// ReservedEnvKey is the environment being rendered. Reserved rather than a
	// parameter because the caller supplies it, never the user — and because it
	// is the value most often needed in a *path* (`overlays/{{ .env }}/`), where
	// a nested lookup would read badly.
	ReservedEnvKey = "env"
)

// InjectReserved adds structured, non-parameter data to a resolved value map.
//
// It must be called *after* Resolve/ResolveLayered, never before: the values it
// adds are lists and nested maps that spec.parameters cannot describe, so
// running them through JSON Schema validation would fail.
//
// A reserved key that collides with a declared parameter, a spec.values entry,
// or a value already in the map is refused — a template that read one thing
// while its schema documented another would be undebuggable. Nothing is
// injected when any key collides, so a caller never sees a half-populated map.
func InjectReserved(t *Template, values map[string]any, reserved map[string]any) error {
	declared := map[string]string{}
	for _, f := range t.Fields() {
		declared[f.Name] = "a declared parameter"
	}
	for name := range t.Spec.Values {
		declared[name] = "a spec.values entry"
	}

	// Sorted so a template with several collisions always reports the same one.
	keys := slices.Sorted(maps.Keys(reserved))
	for _, key := range keys {
		if what, collides := declared[key]; collides {
			return fmt.Errorf("reserved key %q collides with %s", key, what)
		}
		if _, present := values[key]; present {
			return fmt.Errorf("reserved key %q is already set; it cannot be supplied with --set or a values file", key)
		}
	}
	for _, key := range keys {
		values[key] = reserved[key]
	}
	return nil
}

package dashboard

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/deploy"
)

// deployProvider reports what one integration has deployed, where.
//
// Like topologyProvider it never fails: a component that cannot be described
// comes back with Error set rather than an error return, because "we could not
// find out" and "it is not deployed" must not render the same. Which of the two
// it was is the command's business to say, not this package's to guess.
type deployProvider func(ctx context.Context, s integrationSummary) deployState

// deployState is one integration's deployment state, or the reason it has none.
type deployState struct {
	// Status is deploy status's own result, passed through unchanged so that the
	// dashboard and the command line cannot come to different conclusions about
	// the same overlays.
	Status *deploy.StatusResult `json:"status,omitempty"`

	// Error is the command's own message, verbatim — an unconfigured GitOps
	// repository, a component name that matches several, a checkout another
	// deploy is holding. Served rather than restated: those messages already
	// name every way to resolve them, and a paraphrase here would be a second
	// thing to keep true.
	//
	// None of them is a statement about the integration. Only the environments
	// inside Status say whether something is deployed.
	Error string `json:"error,omitempty"`

	// Diagnostics is what the command wrote to stderr, one entry per line:
	// which repository it refreshed, and any environment ArgoCD could not be
	// read for. Provenance for what Status shows, not a failure.
	Diagnostics []string `json:"diagnostics,omitempty"`

	// ReadAt is when the command ran, so a reader can tell how current this is.
	ReadAt time.Time `json:"readAt"`
}

// statusCommandProvider is the default provider: it runs the deploy status
// command with a JSON writer and decodes what it prints.
//
// Calling the command rather than reading the GitOps tree here is deliberate.
// Status already owns every refusal that matters — an unset gitopsRepo, an
// ambiguous component, an overlay that pins a tag, an environment nobody has
// onboarded, an unreachable ArgoCD — and each of those is a case where the
// honest answer is subtle and already written down. A second implementation
// would have to get all of them right again.
//
// Domain and System travel with the component name for the same reason
// deploy status takes them as flags: component names are not unique across a
// GitOps tree, and the command refuses an ambiguous one rather than picking.
func statusCommandProvider(version string) deployProvider {
	userAgent := "intropy-cli/" + version
	return func(ctx context.Context, s integrationSummary) deployState {
		var out, logs bytes.Buffer
		err := deploy.Status(ctx, deploy.StatusOptions{
			Component:    s.Name,
			Domain:       s.Domain,
			System:       s.System,
			OutputFormat: deploy.OutputJSON,
			UserAgent:    userAgent,
			Stdout:       &out,
			Stderr:       &logs,
		})

