	rec := postJSON(t, h, "/api/templates/test-template/create",
		`{"name":"out-dir","values":{"integrationName":"A","name":"Pascal.Name"}}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("status = %d, want 201: %s", rec.Code, rec.Body)
	}
