	if got.OutputDir != "out-dir" {
		t.Errorf("outputDir = %q", got.OutputDir)
	}
	if got.Values["name"] != "Pascal.Name" {
		t.Errorf("values.name = %v, want the form's value to win", got.Values["name"])
	}
}

