// fetchLibrary resolves and downloads the provider's library release. The
// caller owns the returned Library and must Close it.
func (p templatesProvider) fetchLibrary(ctx context.Context) (*template.Library, error) {
	return p.fetchLibraryAt(ctx, p.version)
}

// fetchLibraryAt fetches one release, overriding the provider's pin when
// override is set — the ?version= query parameter, a per-request
// --template-version for trying a release without restarting the dashboard.
func (p templatesProvider) fetchLibraryAt(ctx context.Context, override string) (*template.Library, error) {
	version := p.version
	if override != "" {
		version = override
	}
	return template.FetchLibrary(ctx, template.LibraryOptions{
		Version:       version,
		UserAgent:     p.userAgent,
		Owner:         p.owner,
		Repo:          p.repo,
		GitHubBaseURL: p.githubBaseURL,
	})
}

// listTags returns the library's release tags, newest first.
func (p templatesProvider) listTags(ctx context.Context) ([]string, error) {
	gh := template.NewGitHubClient(nil, p.userAgent, p.githubBaseURL)
	owner, repo := p.owner, p.repo
	if owner == "" || repo == "" {
		owner, repo = template.DefaultLibrary()
	}
	return gh.ListTags(ctx, owner, repo)
}

