// ListTags returns every release tag for owner/repo, newest first — the set
// of versions a caller can pin. Drafts and prereleases are included: an -rc
// tag is how a CI environment stays current, and hiding it here would make
// it unpinnable.
func (g *GitHub) ListTags(ctx context.Context, owner, repo string) ([]string, error) {
	u := fmt.Sprintf("%s/repos/%s/%s/releases?per_page=100", g.BaseURL, owner, repo)
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("Accept", "application/vnd.github+json")
	g.addCommonHeaders(req)

	resp, err := g.HTTP.Do(req)
	if err != nil {
		return nil, fmt.Errorf("github releases: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
		return nil, fmt.Errorf("github releases: %s: %s", resp.Status, string(body))
	}
	var rels []struct {
		TagName string `json:"tag_name"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&rels); err != nil {
		return nil, fmt.Errorf("decode releases: %w", err)
	}
	tags := make([]string, 0, len(rels))
	for _, r := range rels {
		if r.TagName != "" {
			tags = append(tags, r.TagName)
		}
	}
	return tags, nil
}

